using System.Linq;
using UnityEditor;
using UnityEngine;

namespace UnityBox.VisemeBlendshapeOverride.ComponentMigration
{
    public sealed class ComponentReferenceMigrationWindow : EditorWindow
    {
        private readonly List<string> paths = new List<string>();
        private readonly Dictionary<string, string> mappings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        private MigrationPlan plan;
        private MigrationResult result;
        private Vector2 scroll;
        private string error = "";

        [MenuItem("Assets/UnityBox/Viseme Blendshape Override/Repair Component References")]
        public static void Open()
        {
            var window = GetWindow<ComponentReferenceMigrationWindow>("Viseme Component References");
            window.UseProjectSelection();
            window.Show();
        }

        private void UseProjectSelection()
        {
            paths.Clear();
            paths.AddRange(Selection.objects.Select(AssetDatabase.GetAssetPath)
                .Where(path => !string.IsNullOrEmpty(path)).Distinct());
            plan = null;
            result = null;
            error = "";
        }

        private void OnGUI()
        {
            EditorGUILayout.LabelField("Viseme 组件引用迁移 / Component References", EditorStyles.boldLabel);
            EditorGUILayout.HelpBox("手动迁移所选资源中的旧 Viseme Blendshape Override 组件引用，保留组件配置、对象身份和 metadata。"
                + "拖入资源或使用 Project 当前选择，再点击 Analyze 查看结果或 Migrate Selected Assets 批量执行。"
                + "打开项目和导入资源不会自动执行迁移。", MessageType.Info);
            using (new EditorGUILayout.HorizontalScope())
            {
                if (GUILayout.Button("Use Project Selection")) UseProjectSelection();
                if (GUILayout.Button("Clear")) { paths.Clear(); plan = null; result = null; }
            }
            var drop = GUILayoutUtility.GetRect(0, 40, GUILayout.ExpandWidth(true));
            GUI.Box(drop, "Drop Prefab / Scene / .asset / Assets folder here");
            if (drop.Contains(Event.current.mousePosition)
                && (Event.current.type == EventType.DragUpdated || Event.current.type == EventType.DragPerform))
            {
                DragAndDrop.visualMode = DragAndDropVisualMode.Copy;
                if (Event.current.type == EventType.DragPerform)
                {
                    DragAndDrop.AcceptDrag();
                    paths.AddRange(DragAndDrop.objectReferences.Select(AssetDatabase.GetAssetPath)
                        .Concat(DragAndDrop.paths).Where(path => !string.IsNullOrEmpty(path) && !paths.Contains(path)).Distinct());
                    plan = null;
                    result = null;
                }
                Event.current.Use();
            }
            foreach (string path in paths) EditorGUILayout.LabelField(path, EditorStyles.miniLabel);
            using (new EditorGUI.DisabledScope(paths.Count == 0 || EditorApplication.isCompiling || EditorApplication.isUpdating))
            using (new EditorGUILayout.HorizontalScope())
            {
                if (GUILayout.Button("Analyze")) Analyze();
                if (GUILayout.Button("Migrate Selected Assets"))
                {
                    Analyze();
                    if (plan != null)
                    {
                        try { result = MigrationEngine.Apply(plan); }
                        catch (Exception exception) { error = exception.Message; }
                    }
                }
            }
            if (!string.IsNullOrEmpty(error)) EditorGUILayout.HelpBox(error, MessageType.Error);
            if (result != null)
            {
                EditorGUILayout.HelpBox("已迁移 " + result.RepairedComponents + " 个组件，写入 " + result.ChangedAssets.Count
                    + " 个资源。歧义、重复或正在编辑的资源保留原样。", MessageType.Info);
                if (!string.IsNullOrEmpty(result.BackupDirectory))
                {
                    EditorGUILayout.SelectableLabel(result.BackupDirectory, GUILayout.Height(32));
                    if (GUILayout.Button("Show Backup")) EditorUtility.RevealInFinder(result.BackupDirectory);
                }
                foreach (var issue in result.Issues)
                    EditorGUILayout.HelpBox(issue.AssetPath + "\n" + issue.Message, MessageType.Warning);
            }
            if (plan == null) return;
            scroll = EditorGUILayout.BeginScrollView(scroll);
            EditorGUILayout.LabelField("扫描 " + plan.ScannedAssets.Count + " 个资源；可迁移 "
                + plan.Entries.Count(entry => entry.Status == MigrationStatus.Ready) + " 个组件。", EditorStyles.boldLabel);
            DrawMappings();
            foreach (var issue in plan.Issues)
                EditorGUILayout.HelpBox(issue.AssetPath + "\n" + issue.Message, MessageType.Warning);
            foreach (var entry in plan.Entries)
            {
                using (new EditorGUILayout.VerticalScope(EditorStyles.helpBox))
                {
                    EditorGUILayout.LabelField(entry.Status + "  " + entry.AssetPath, EditorStyles.boldLabel);
                    EditorGUILayout.LabelField("GameObject: " + entry.GameObjectName);
                    EditorGUILayout.LabelField("fileID: " + entry.ComponentFileId + "  " + entry.TypeName);
                    if (entry.EditorClassIdentifier.Length > 0)
                        EditorGUILayout.LabelField("Class: " + entry.EditorClassIdentifier, EditorStyles.wordWrappedMiniLabel);
                    if (entry.SerializedFields.Count > 0)
                        EditorGUILayout.LabelField("Fields: " + string.Join(", ", entry.SerializedFields), EditorStyles.wordWrappedMiniLabel);
                    if (entry.CandidateTypes.Count > 0 && entry.Status == MigrationStatus.Ambiguous)
                        EditorGUILayout.LabelField("Candidates: " + string.Join(", ", entry.CandidateTypes), EditorStyles.wordWrappedMiniLabel);
                    EditorGUILayout.SelectableLabel(entry.LegacyGuid + " → " + (entry.TargetGuid.Length == 0 ? "?" : entry.TargetGuid), GUILayout.Height(18));
                    EditorGUILayout.LabelField(entry.Details, EditorStyles.wordWrappedMiniLabel);
                }
            }
            if (plan.Entries.Count == 0) EditorGUILayout.HelpBox("没有发现可迁移的未知脚本引用。已有有效引用保持原样。", MessageType.Info);
