        private void Analyze()
        {
            result = null;
            error = "";
            try { plan = MigrationEngine.Scan(paths, mappings); }
            catch (Exception exception) { plan = null; error = exception.Message; }
        }

        private void DrawMappings()
        {
            var ambiguous = plan.Entries.Where(entry => entry.Status == MigrationStatus.Ambiguous)
                .GroupBy(entry => entry.LegacyGuid, StringComparer.OrdinalIgnoreCase).ToArray();
            if (ambiguous.Length == 0) return;
            EditorGUILayout.LabelField("GUID 类型映射 / GUID Type Mapping", EditorStyles.boldLabel);
            EditorGUILayout.HelpBox("仅在你知道旧脚本身份时选择类型；同一 GUID 选择一次，随后批量执行。"
                + "其它插件的未知引用不会作为本插件候选。", MessageType.Info);
            var available = plan.TargetTypes.Where(target => target.Available).ToArray();
            string[] labels = new[] { "Leave unchanged" }.Concat(available.Select(target => target.DisplayName)).ToArray();
            foreach (var group in ambiguous)
            {
                string previous = mappings.TryGetValue(group.Key, out var mapped) ? mapped : "";
                int selected = Array.FindIndex(available, target => target.TypeName == previous) + 1;
                EditorGUILayout.SelectableLabel(group.Key, GUILayout.Height(18));
                int next = EditorGUILayout.Popup("Target type", selected, labels);
                if (next == selected) continue;
                if (next == 0) mappings.Remove(group.Key);
                else mappings[group.Key] = available[next - 1].TypeName;
            }
        }
    }
}
